  async function handleRosterUpload(e) { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = async () => { setBusy(true); try { const parsed = parseCSV(String(reader.result || "")); if (!parsed.length) throw new Error("CSV file is empty."); const headers = Object.keys(parsed[0]).map((h) => h.toUpperCase()), missing = REQUIRED_ROSTER_COLUMNS.filter((column) => !headers.includes(column)); if (missing.length) throw new Error(`Missing columns: ${missing.join(", ")}`); const uploadRows = parsed.map(toRosterRow).filter((row) => row.rn && row.name), seen = new Set(), dedupedRows = uploadRows.filter((row) => { if (seen.has(row.rn)) return false; seen.add(row.rn); return true; }); if (!dedupedRows.length) throw new Error("No valid roster rows found."); if (!supabase) { setRosterRows(dedupedRows); setEventRows([]); setRnInput(""); setAdminSelectedRN(dedupedRows[0]?.rn || ""); setMessage(`Roster loaded locally: ${dedupedRows.length} soldiers; previous records reset. Add Supabase env variables for shared multi-phone database mode.`); return; } const { error: deleteError } = await supabase.from("aft_event_records").delete().neq("rn", "__never_match__"); if (deleteError) throw deleteError; const { error: rosterDeleteError } = await supabase.from("aft_roster").delete().neq("rn", "__never_match__"); if (rosterDeleteError) throw rosterDeleteError; const { error } = await supabase.from("aft_roster").upsert(dedupedRows, { onConflict: "rn" }); if (error) throw error; setMessage(`Roster uploaded to shared database: ${dedupedRows.length} soldiers; previous roster and records reset.`); await loadAllData(); } catch (error) { setMessage(`Roster upload failed: ${error.message}`); } finally { if (mountedRef.current) setBusy(false); } }; reader.onerror = () => setMessage("Roster upload failed: file could not be read."); reader.readAsText(file); e.target.value = ""; }
